// Generates supabase/seed.sql from src/data/products.js.
// Usage:  node scripts/generate-seed.mjs
import { writeFileSync } from 'node:fs';
import { categories, products } from '../src/data/products.js';

const q = (v) => (v == null || v === '' ? 'null' : `'${String(v).replace(/'/g, "''")}'`);

const lines = [
  '-- Amba Traders — initial catalogue (generated by scripts/generate-seed.mjs)',
  '-- Safe to re-run: existing rows are updated, stock is left untouched.',
  '',
  'insert into public.categories (id, name, blurb, cover, sort) values',
  categories
    .map((c, i) => `  (${q(c.id)}, ${q(c.name)}, ${q(c.blurb)}, ${q(c.cover)}, ${i})`)
    .join(',\n'),
  'on conflict (id) do update set name = excluded.name, blurb = excluded.blurb, cover = excluded.cover, sort = excluded.sort;',
  '',
  'insert into public.products (dno, name, colour, category_id, fabric, pieces, bottom, dupatta, sizes_note, description, image, thumb, model, price, sort) values',
  products
    .map(
      (p, i) =>
        `  (${p.dno}, ${q(p.name)}, ${q(p.colour)}, ${q(p.category)}, ${q(p.fabric)}, ${p.pieces}, ${q(p.bottom)}, ${q(p.dupatta)}, ${q(p.sizes)}, ${q(p.description)}, ${q(p.image)}, ${q(p.thumb)}, ${q(p.model)}, ${p.price ?? 'null'}, ${i})`,
    )
    .join(',\n'),
  'on conflict (dno) do update set name = excluded.name, colour = excluded.colour, category_id = excluded.category_id,',
  '  fabric = excluded.fabric, pieces = excluded.pieces, bottom = excluded.bottom, dupatta = excluded.dupatta,',
  '  sizes_note = excluded.sizes_note, description = excluded.description, image = excluded.image,',
  '  thumb = excluded.thumb, model = excluded.model, sort = excluded.sort;',
  '',
];

writeFileSync(new URL('../supabase/seed.sql', import.meta.url), lines.join('\n'));
console.log(`seed.sql written: ${categories.length} categories, ${products.length} products`);
